package com.bank.summary;

import java.util.*;
import java.util.logging.*;

public class SummaryDemo {
    private static final Logger log = Logger.getLogger("Summary");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // unordered input map (as a HashMap would be)
        Map<String, Long> counts = new HashMap<>();
        counts.put("Trading", 3L);
        counts.put("Risk", 2L);
        counts.put("Settlement", 1L);
        SummaryService service = new SummaryService();

        String summary = service.departmentSummary(counts);
        log.info(() -> "Headcount summary: " + summary);
        log.info(() -> "Empty summary: " + service.departmentSummary(Map.of()));
    }
}

// ─── Would be in service/SummaryService.java ───
class SummaryService {
    // stream entrySet → sort by key → format → join with delimiter/prefix/suffix
    String departmentSummary(Map<String, Long> counts) {
        return counts.entrySet().stream()
            .sorted(Map.Entry.comparingByKey())               // department asc, deterministic
            .map(e -> e.getKey() + "=" + e.getValue())         // Entry → "Risk=2"
            .collect(java.util.stream.Collectors.joining(", ", "[", "]")); // delimiter+wrap
    }
}
